import sys
from collections import defaultdict

MOD = 998244353

def factorize(x):
    factors = []
    d = 2
    while d * d <= x:
        if x % d == 0:
            e = 0
            while x % d == 0:
                x //= d
                e += 1
            factors.append((d, e))
        d += 1
    if x > 1:
        factors.append((x, 1))
    return factors

data = list(map(int, sys.stdin.buffer.read().split()))
n = data[0]
a = data[1:]

by_prime = defaultdict(list)
for i, x in enumerate(a):
    for p, e in factorize(x):
        by_prime[p].append((i, e))

answer = 1
for p, edges in by_prime.items():
    edge_exp = [0] * (n - 1)
    for i, e in edges:
        edge_exp[i] = e

    # State: (current height, minimum height) -> total weight.
    # The initial vertex has height 0 and contributes no factor.
    dp = {(0, 0): 1}
    for e in edge_exp:
        ndp = defaultdict(int)
        for (height, low), ways in dp.items():
            for sign in (-1, 1):
                nh = height + sign * e
                nl = min(low, nh)
                key = (nh, nl)
                ndp[key] = (ndp[key] + ways * pow(p, nh - nl, MOD)) % MOD
        dp = ndp

    answer = answer * (sum(dp.values()) % MOD) % MOD

print(answer)

