import heapq
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        at = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            if a > b:
                a, b = b, a
            at[b].append((a, i))
        heap = []
        gains = [0] * len(conflictingPairs)
        base = 0
        for r in range(1, n + 1):
            for a, i in at[r]:
                heapq.heappush(heap, (-a, i))
            if heap:
                topa, topid = heap[0]
                topa = -topa
                base += r - topa
                if len(heap) > 1:
                    x = heap[1]
                    y = heap[2] if len(heap) > 2 else None
                    second = -min(x[0], y[0]) if y is not None else -x[0]
                else:
                    second = 0
                gains[topid] += topa - second
            else:
                base += r
        return base + max(gains)

