import sys

def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    it=iter(data)
    n=next(it); m=next(it); q=next(it)
    edges=[]
    for _ in range(m):
        a=next(it)-1; b=next(it)-1; c=next(it)
        edges.append((a,b,c))
    queries=[]
    for _ in range(q):
        t=next(it)
        if t==1: queries.append((1,next(it)-1))
        else: queries.append((2,next(it)-1,next(it)-1))
    closed=[False]*m
    INF=10**30
    def apsp():
        d=[[INF]*n for _ in range(n)]
        for i in range(n): d[i][i]=0
        for i,(a,b,c) in enumerate(edges):
            if not closed[i]: d[a][b]=d[b][a]=c
        for k in range(n):
            dk=d[k]
            for i in range(n):
                di=d[i]; x=di[k]
                if x==INF: continue
                for j in range(n):
                    v=x+dk[j]
                    if v<di[j]: di[j]=v
        return d
    d=apsp()
    out=[]
    for qu in queries:
        if qu[0]==1:
            idx=qu[1]; closed[idx]=True; d=apsp()
        else:
            x,y=qu[1:]
            out.append(str(d[x][y] if d[x][y]<INF else -1))
    sys.stdout.write('\n'.join(out))

main()

