class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        mod = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1
        for _ in range(n):
            ndp = [0] * (x + 1)
            for k, v in enumerate(dp):
                if v:
                    ndp[k] = (ndp[k] + v * k) % mod
                    if k < x:
                        ndp[k + 1] = (ndp[k + 1] + v * (x - k) * y) % mod
            dp = ndp
        return sum(dp) % mod

if __name__ == '__main__':
    s = Solution()
    print(s.numberOfWays(1, 2, 3))
    print(s.numberOfWays(5, 2, 1))
    print(s.numberOfWays(3, 3, 4))

