class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for i in range(1, n + 1):
            comb[i][0] = comb[i][i] = 1
            for j in range(1, i):
                comb[i][j] = (comb[i - 1][j - 1] + comb[i - 1][j]) % MOD
        good = [False] * (n + 1)
        for x in range(1, n + 1):
            y = x
            steps = 0
            while y != 1:
                y = y.bit_count()
                steps += 1
            good[x] = steps <= k - 1
        ans = 0
        ones = 0
        for i, ch in enumerate(s):
            rem = n - i - 1
            if ch == '1':
                for j in range(1, n + 1):
                    need = j - ones
                    if 0 <= need <= rem and good[j]:
                        ans += comb[rem][need]
                ones += 1
        return ans % MOD

