def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    n,m=data[0],data[1]
    rows=[0]*n
    p=2
    for _ in range(m):
        u,v=data[p]-1,data[p+1]-1
        p+=2
        rows[u]|=1<<v
        rows[v]|=1<<u
    pivot_cols=[]
    r=0
    for c in range(n):
        k=next((i for i in range(r,n) if (rows[i]>>c)&1),None)
        if k is None:
            continue
        rows[r],rows[k]=rows[k],rows[r]
        for i in range(n):
            if i!=r and ((rows[i]>>c)&1):
                rows[i]^=rows[r]
        pivot_cols.append(c)
        r+=1
    pivset=set(pivot_cols)
    free=[c for c in range(n) if c not in pivset]
    vals=[0]*n
    for b,f in enumerate(free):
        sol=1<<f
        for i,c in enumerate(pivot_cols):
            if (rows[i]>>f)&1:
                sol|=1<<c
        bit=1<<b
        while sol:
            x=sol&-sol
            vals[x.bit_length()-1]|=bit
            sol-=x
    if any(x==0 for x in vals):
        print('No')
    else:
        print('Yes')
        print(*vals)

