from functools import lru_cache
from typing import List
class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        dirs = ((-1,1),(1,1),(1,-1),(-1,-1))
        cw = (1,2,3,0)
        @lru_cache(None)
        def go(r, c, d, can_turn):
            v = grid[r][c]
            if v == 1:
                return 0
            dr, dc = dirs[d]
            want = 0 if v == 2 else 2
            best = 0
            nr, nc = r+dr, c+dc
            if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == want:
                best = go(nr, nc, d, can_turn)
            if can_turn:
                td = cw[d]
                dr, dc = dirs[td]
                nr, nc = r+dr, c+dc
                if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == want:
                    best = max(best, go(nr, nc, td, False))
            return 1 + best
        ans = 0
        for r in range(n):
            for c in range(m):
                if grid[r][c] == 1:
                    ans = max(ans, 1)
                    for d,(dr,dc) in enumerate(dirs):
                        nr,nc=r+dr,c+dc
                        if 0<=nr<n and 0<=nc<m and grid[nr][nc]==2:
                            ans=max(ans,1+go(nr,nc,d,True))
        return ans

