from typing import List
import math
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i
        odds = set(range(1, n + 1, 2))
        evens = set(range(2, n + 1, 2))
        ans = []
        prev_odd = None
        for pos in range(n):
            chosen = False
            for x in sorted(odds | evens):
                is_odd = x in odds
                if prev_odd is not None and is_odd == prev_odd:
                    continue
                ro = len(odds) - (1 if is_odd else 0)
                re = len(evens) - (0 if is_odd else 1)
                m = n - pos - 1
                if m:
                    first_odd = not is_odd
                    need_o = (m + 1) // 2 if first_odd else m // 2
                    need_e = m - need_o
                else:
                    need_o = need_e = 0
                ways = fact[ro] * fact[re] if ro == need_o and re == need_e else 0
                if k > ways:
                    k -= ways
                else:
                    if ways == 0:
                        return []
                    ans.append(x)
                    (odds if is_odd else evens).remove(x)
                    prev_odd = is_odd
                    chosen = True
                    break
            if not chosen:
                return []
        return ans

