class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7
        cells = m * n
        total = n * n * (m * (m * m - 1) // 6) + m * m * (n * (n * n - 1) // 6)
        ways = 1
        for i in range(1, k - 1):
            ways = ways * (cells - 2 - i + 1) % MOD
            ways = ways * pow(i, MOD - 2, MOD) % MOD
        return total % MOD * ways % MOD

