class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        powers = [1 % k] * n
        for i in range(1, n):
            powers[i] = powers[i - 1] * 10 % k
        weights = []
        for j in range(m):
            if n % 2 and j == m - 1:
                weights.append(powers[j])
            else:
                weights.append((powers[j] + powers[n - 1 - j]) % k)

        suffix = [bytearray(k) for _ in range(m + 1)]
        suffix[m][0] = 1
        for i in range(m - 1, -1, -1):
            row = suffix[i]
            nxt = suffix[i + 1]
            w = weights[i]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        row[(r + d * w) % k] = 1

        digits = []
        current = 0
        for i, w in enumerate(weights):
            lo = 1 if i == 0 else 0
            for d in range(9, lo - 1, -1):
                need = (-(current + d * w)) % k
                if suffix[i + 1][need]:
                    digits.append(str(d))
                    current = (current + d * w) % k
                    break
        left = ''.join(digits)
        return left + (left[:-1][::-1] if n % 2 else left[::-1])

