from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n=len(nums)
        nxt=[n]*n
        st=[]
        for i in range(n-1,-1,-1):
            while st and nums[st[-1]]<=nums[i]: st.pop()
            if st: nxt[i]=st[-1]
            st.append(i)
        pref=[0]*(n+1)
        for i,x in enumerate(nums): pref[i+1]=pref[i]+x
        levels=n.bit_length()
        jump=[nxt]
        weight=[[(nums[i]*(nxt[i]-i-1)-(pref[nxt[i]]-pref[i+1])) for i in range(n)]]
        for _ in range(1,levels):
            prev=jump[-1]; pw=weight[-1]
            j=[n]*n; w=[0]*n
            for i in range(n):
                mid=prev[i]
                if mid<n:
                    j[i]=prev[mid]
                    w[i]=pw[i]+pw[mid]
            jump.append(j); weight.append(w)
        def cost(l,r):
            p=l; ans=0
            for b in range(levels-1,-1,-1):
                if p==n: break
                q=jump[b][p]
                if q<=r+1:
                    ans+=weight[b][p]; p=q
            if p<=r:
                ans+=nums[p]*(r-p)-(pref[r+1]-pref[p+1])
            return ans
        ans=0; r=-1
        for l in range(n):
            if r<l-1: r=l-1
            while r+1<n and cost(l,r+1)<=k: r+=1
            ans+=r-l+1
        return ans

