    if sz[ra]<sz[rb]: ra,rb=rb,ra; xa,xb=xb,xa
    p[rb]=ra; xr[rb]=xa^xb^v; sz[ra]+=sz[rb]
  # horizontal id row*w+col; vertical id hw+row*w+col (edge top->bottom)
