from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        n = len(s)
        occ = []
        for w in parts:
            arr = []
            if w:
                pos = s.find(w)
                while pos != -1:
                    arr.append(pos)
                    pos = s.find(w, pos + 1)
            occ.append(arr)
        ids = [i for i, w in enumerate(parts) if w]
        if not ids:
            return 0
        if any(not occ[i] for i in ids):
            return -1
        first = ids[0]
        best = n + 1
        for start in occ[first]:
            end = start + len(parts[first])
            possible = True
            for idx in ids[1:]:
                arr = occ[idx]
                k = bisect_left(arr, end)
                if k == len(arr):
                    possible = False
                    break
                end = arr[k] + len(parts[idx])
            if possible:
                best = min(best, end - start)
        return best if best <= n else -1

