def main():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data:
        return
    n,m=data[0],data[1]
    g=[[] for _ in range(n)]
    p=2
    for _ in range(m):
        x,y,z=data[p]-1,data[p+1]-1,data[p+2]
        p+=3
        g[x].append((y,z))
        g[y].append((x,z))
    val=[-1]*n
    ans=[0]*n
    for s in range(n):
        if val[s]!=-1:
            continue
        val[s]=0
        st=[s]
        comp=[]
        ok=True
        while st:
            v=st.pop()
            comp.append(v)
            for w,z in g[v]:
                nv=val[v]^z
                if val[w]==-1:
                    val[w]=nv
                    st.append(w)
                elif val[w]!=nv:
                    ok=False
        if not ok:
            print(-1)
            return
        cnt=[0]*30
        for v in comp:
            x=val[v]
            for b in range(30):
                cnt[b]+=(x>>b)&1
        base=0
        size=len(comp)
        for b in range(30):
            if cnt[b]>size-cnt[b]:
                base|=1<<b
        for v in comp:
            ans[v]=val[v]^base
    print(*ans)

if __name__=='__main__':
    main()

