def bfs(a,n):
 s=tuple(a); q=deque([(s,0)]); seen={s}
 while q:
  x,d=q.popleft()
  yield x,d
  for i in range(n):
   y=[0]*n
   for j,c in enumerate(x):
    if c:y[j+(1 if j<i else -1 if j>i else 0)]+=c
   y=tuple(y)
   if y not in seen:seen.add(y);q.append((y,d+1))

def pred(a,b,n):
