from typing import List
class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for i in range(1, n):
            children[parent[i]].append(i)
        order = []
        stack = [(0, 0)]
        while stack:
            x, state = stack.pop()
            if state:
                order.append(x)
            else:
                stack.append((x, 1))
                for y in reversed(children[x]):
                    stack.append((y, 0))
        t = ''.join(s[x] for x in order)
        pos = [0] * n
        for i, x in enumerate(order):
            pos[x] = i
        size = [1] * n
        for x in order:
            if x != 0:
                size[parent[x]] += size[x]
        m = n
        d1 = [0] * m
        l = 0
        r = -1
        for i in range(m):
            k = 1 if i > r else min(d1[l + r - i], r - i + 1)
            while i - k >= 0 and i + k < m and t[i - k] == t[i + k]:
                k += 1
            d1[i] = k
            if i + k - 1 > r:
                l, r = i - k + 1, i + k - 1
        d2 = [0] * m
        l = 0
        r = -1
        for i in range(m):
            k = 0 if i > r else min(d2[l + r - i + 1], r - i + 1)
            while i - k - 1 >= 0 and i + k < m and t[i - k - 1] == t[i + k]:
                k += 1
            d2[i] = k
            if i + k - 1 > r:
                l, r = i - k, i + k - 1
        ans = [False] * n
        for x in range(n):
            length = size[x]
