from typing import List
class Solution:
    def maxEnergyBoost(self, energyDrinkA: List[int], energyDrinkB: List[int]) -> int:
        n = len(energyDrinkA)
        da = [0] * n
        db = [0] * n
        da[0] = energyDrinkA[0]
        db[0] = energyDrinkB[0]
        for i in range(1, n):
            da[i] = energyDrinkA[i] + max(da[i-1], db[i-2] if i >= 2 else 0)
            db[i] = energyDrinkB[i] + max(db[i-1], da[i-2] if i >= 2 else 0)
        return max(da[-1], db[-1])

