    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        mins = [None] * k
        mins[0] = 0
        pref = 0
        ans = -10**30
        for t, x in enumerate(nums, 1):
            pref += x
            r = t % k
            old = mins[r]
            if old is not None:
                val = pref - old
                if val > ans:
                    ans = val
            if old is None or pref < old:
                mins[r] = pref
        return ans

