import sys
from itertools import permutations

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    it = iter(data)
    n = next(it)
    mg = next(it)
    g = [[0] * n for _ in range(n)]
    for _ in range(mg):
        u = next(it) - 1
        v = next(it) - 1
        g[u][v] = g[v][u] = 1
    mh = next(it)
    h = [[0] * n for _ in range(n)]
    for _ in range(mh):
        u = next(it) - 1
        v = next(it) - 1
        h[u][v] = h[v][u] = 1
    cost = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            x = next(it)
            cost[i][j] = cost[j][i] = x
    best = 10**30
    for p in permutations(range(n)):
        total = 0
        for i in range(n):
            pi = p[i]
            for j in range(i + 1, n):
                if g[i][j] != h[pi][p[j]]:
                    total += cost[pi][p[j]]
        if total < best:
            best = total
    print(best)

if __name__ == '__main__':
    main()

