from typing import List
class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        dp = [1] * n
        done = sum(x == 0 for x in nums)
        if done == n:
            return 0
        for k, (l, r, val) in enumerate(queries, 1):
            for i in range(l, r + 1):
                if nums[i] and not ((dp[i] >> nums[i]) & 1):
                    dp[i] |= dp[i] << val
                    if (dp[i] >> nums[i]) & 1:
                        done += 1
            if done == n:
                return k
        return -1

