import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        limit = 10000
        prime = bytearray(b'\x01') * limit
        prime[0:2] = b'\x00\x00'
        for i in range(2, 100):
            if prime[i]:
                prime[i*i:limit:i] = b'\x00' * (((limit - 1 - i*i)//i) + 1)
        if prime[n] or prime[m]:
            return -1
        length = len(str(n))
        low = 10 ** (length - 1)
        high = 10 ** length
        powers = [10 ** i for i in range(length)]
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if dist.get(x) != cost:
                continue
            if x == m:
                return cost
            for p in powers:
                d = (x // p) % 10
                if d < 9:
                    y = x + p
                    if y < high and not prime[y]:
                        nc = cost + y
                        if nc < dist.get(y, 10**30):
                            dist[y] = nc
                            heapq.heappush(heap, (nc, y))
                if d > 0:
                    y = x - p
                    if y >= low and not prime[y]:
                        nc = cost + y
                        if nc < dist.get(y, 10**30):
                            dist[y] = nc
                            heapq.heappush(heap, (nc, y))
        return -1

